svg.script:
(function () {
  'use strict';
  var NS = 'http://www.w3.org/2000/svg';
  var $ = function (id) { return document.getElementById(id); };

  // ---- fixed geometry (screen units of the viewBox) ----
  var CRANK = { x: 390, y: 415 }, CRANK_R = 38;
  var REAR = { x: 250, y: 405 }, FRONT = { x: 560, y: 405 }, WHEEL_R = 95;
  var HIP_A = { x: 345, y: 257 }, HIP_B = { x: 337, y: 252 };
  var THIGH = 98, SHIN = 110;
  var SOLE = 4;                         // sole sits 4px above pedal axle (on the platform)
  var ANKLE = { x: -4, y: -15 };        // ankle relative to sole anchor
  var CYCLE = 2;                        // seconds per pedal revolution at 1x
  var WHEEL_CIRC = 2 * Math.PI * WHEEL_R;
  var ROAD_TILE = WHEEL_CIRC / 3;       // road pattern repeats 3x per revolution -> seamless
  var CHAIN_CIRC = 2 * Math.PI * 26, CHAIN_TILE = CHAIN_CIRC / 24;
  var HILL_FAR = 200, HILL_NEAR = 260, TREE_TILE = 300;

  var state = { phase: 0, paused: false, rate: 1 };
  var manual = false;
  var lastT = null;

  // ---- build periodic decorations ----
  function spokes(id, c) {
    var g = $(id);
    for (var i = 0; i < 18; i++) {
      var a = i * Math.PI * 2 / 18, off = (i % 2 ? 1 : -1) * 0.12;
      var l = document.createElementNS(NS, 'line');
      l.setAttribute('x1', (c.x + 5 * Math.cos(a + off)).toFixed(2));
      l.setAttribute('y1', (c.y + 5 * Math.sin(a + off)).toFixed(2));
      l.setAttribute('x2', (c.x + 86 * Math.cos(a)).toFixed(2));
      l.setAttribute('y2', (c.y + 86 * Math.sin(a)).toFixed(2));
      g.appendChild(l);
    }
  }
  spokes('spokes-rear', REAR);
  spokes('spokes-front', FRONT);

  function hillPath(period, base, amp, amp2, x0, x1) {
    var d = 'M' + x0 + ' 520';
    for (var x = x0; x <= x1; x += 5) {
      var t = 2 * Math.PI * x / period;
      var y = base - amp * (0.5 + 0.5 * Math.sin(t)) - amp2 * Math.sin(2 * t + 1);
      d += ' L' + x + ' ' + y.toFixed(1);
    }
    return d + ' L' + x1 + ' 520 Z';
  }
  $('hills-far-path').setAttribute('d', hillPath(HILL_FAR, 440, 70, 8, -HILL_FAR, 800 + HILL_FAR));
  $('hills-near-path').setAttribute('d', hillPath(HILL_NEAR, 482, 48, 6, -HILL_NEAR, 800 + HILL_NEAR));

  function el(tag, attrs, parent) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    parent.appendChild(e);
    return e;
  }
  var trees = $('trees');
  for (var tx = -TREE_TILE; tx < 800 + TREE_TILE; tx += TREE_TILE) {
    el('rect', { x: tx + 60, y: 448, width: 6, height: 42, fill: '#6b5a48' }, trees);
    el('circle', { cx: tx + 63, cy: 440, r: 24, fill: '#5f9a6c' }, trees);
    el('circle', { cx: tx + 52, cy: 448, r: 14, fill: '#6faa79' }, trees);
    el('rect', { x: tx + 200, y: 462, width: 5, height: 28, fill: '#6b5a48' }, trees);
    el('path', { d: 'M' + (tx + 202.5) + ' 418 l18 48 h-36 z', fill: '#4f8a63' }, trees);
  }
  var marks = $('road-marks');
  for (var mx = -ROAD_TILE; mx < 800 + ROAD_TILE; mx += ROAD_TILE) {
    el('rect', { x: mx.toFixed(2), y: 556, width: (ROAD_TILE * 0.5).toFixed(2), height: 7, rx: 3, fill: '#f1e3b2' }, marks);
    el('rect', { x: (mx + ROAD_TILE * 0.62).toFixed(2), y: 528, width: 10, height: 3, rx: 1.5, fill: '#6c7480' }, marks);
    el('rect', { x: (mx + ROAD_TILE * 0.2).toFixed(2), y: 584, width: 16, height: 3, rx: 1.5, fill: '#3b4048' }, marks);
  }
  var tufts = $('grass-tufts');
  for (var gx = -ROAD_TILE; gx < 800 + ROAD_TILE; gx += ROAD_TILE / 2) {
    el('path', { d: 'M' + gx.toFixed(2) + ' 502 l3 -10 l2 8 l4 -12 l2 12 l3 -7 l2 9 z', fill: '#5f9150' }, tufts);
  }

  // ---- refs ----
  var R = {
    wheelRear: $('wheel-rear'), wheelFront: $('wheel-front'),
    crankNear: $('crank-near'), crankFar: $('crank-far'), chainring: $('chainring'),
    pedalA: $('pedal-a-platform'), pedalB: $('pedal-b-platform'),
    footA: $('foot-a'), footB: $('foot-b'),
    aThigh: $('leg-a-thigh'), aThighOl: $('leg-a-thigh-ol'), aShin: $('leg-a-shin'), aShinOl: $('leg-a-shin-ol'), aKnee: $('leg-a-knee'),
    bThigh: $('leg-b-thigh'), bThighOl: $('leg-b-thigh-ol'), bShin: $('leg-b-shin'), bKnee: $('leg-b-knee'),
    torso: $('torso'), head: $('head'), wingNear: $('wing-near'), wingFar: $('wing-far'),
    chain: $('chain'), hillsFar: $('hills-far'), hillsNear: $('hills-near'), trees: trees,
    marks: marks, tufts: tufts,
    play: document.querySelector('[data-testid="pelican-play"]'),
    speed: document.querySelector('[data-testid="pelican-speed"]')
  };
  R.chain.setAttribute('stroke-dasharray', (CHAIN_TILE * 0.55).toFixed(4) + ' ' + (CHAIN_TILE * 0.45).toFixed(4));

  // two-bone IK, knee bends forward (+x)
  function knee(h, a) {
    var dx = a.x - h.x, dy = a.y - h.y;
    var d = Math.sqrt(dx * dx + dy * dy);
    d = Math.max(Math.abs(THIGH - SHIN) + 1, Math.min(THIGH + SHIN - 0.5, d));
    var phi = Math.atan2(dy, dx);
    var c = (THIGH * THIGH + d * d - SHIN * SHIN) / (2 * THIGH * d);
    var alpha = Math.acos(Math.max(-1, Math.min(1, c)));
    return { x: h.x + THIGH * Math.cos(phi - alpha), y: h.y + THIGH * Math.sin(phi - alpha) };
  }
  function seg(p, q) { return 'M' + p.x.toFixed(2) + ' ' + p.y.toFixed(2) + ' L' + q.x.toFixed(2) + ' ' + q.y.toFixed(2); }
  function tr(x, y) { return 'translate(' + x.toFixed(3) + ' ' + y.toFixed(3) + ')'; }
  function rot(a, c) { return 'rotate(' + a.toFixed(4) + ' ' + c.x + ' ' + c.y + ')'; }
  function mod(v, m) { v = v % m; return v < 0 ? v + m : v; }

  // ---- single render path shared by rAF playback and manual step() ----
  function render() {
    var p = state.phase;
    var deg = p * 360;                  // clockwise = forward motion to the right
    var rad = p * 2 * Math.PI;
    var tw = Math.sin(2 * rad);         // two strokes per revolution

    R.wheelRear.setAttribute('transform', rot(deg, REAR));
    R.wheelFront.setAttribute('transform', rot(deg, FRONT));
    R.crankNear.setAttribute('transform', rot(deg, CRANK));
    R.crankFar.setAttribute('transform', rot(deg, CRANK));
    R.chainring.setAttribute('transform', rot(deg, CRANK));

    var pa = { x: CRANK.x + CRANK_R * Math.cos(rad), y: CRANK.y + CRANK_R * Math.sin(rad) };
    var pb = { x: CRANK.x - CRANK_R * Math.cos(rad), y: CRANK.y - CRANK_R * Math.sin(rad) };
    R.pedalA.setAttribute('transform', tr(pa.x, pa.y));
    R.pedalB.setAttribute('transform', tr(pb.x, pb.y));

    // slight ankling: toe dips on the down stroke
    var tiltA = 8 * Math.sin(rad), tiltB = -8 * Math.sin(rad);
    var fa = { x: pa.x, y: pa.y - SOLE }, fb = { x: pb.x, y: pb.y - SOLE };
    R.footA.setAttribute('transform', tr(fa.x, fa.y) + ' rotate(' + (tiltA * 0.4).toFixed(3) + ')');
    R.footB.setAttribute('transform', tr(fb.x, fb.y) + ' rotate(' + (tiltB * 0.4).toFixed(3) + ')');

    function ankleOf(f, tilt) {
      var t = tilt * 0.4 * Math.PI / 180, c = Math.cos(t), s = Math.sin(t);
      return { x: f.x + ANKLE.x * c - ANKLE.y * s, y: f.y + ANKLE.x * s + ANKLE.y * c };
    }
    var aa = ankleOf(fa, tiltA), ab = ankleOf(fb, tiltB);
    var ka = knee(HIP_A, aa), kb = knee(HIP_B, ab);
    var tA = seg(HIP_A, ka), sA = seg(ka, aa);
    R.aThigh.setAttribute('d', tA); R.aThighOl.setAttribute('d', tA);
    R.aShin.setAttribute('d', sA); R.aShinOl.setAttribute('d', sA);
    R.aKnee.setAttribute('cx', ka.x.toFixed(2)); R.aKnee.setAttribute('cy', ka.y.toFixed(2));
    var tB = seg(HIP_B, kb);
    R.bThigh.setAttribute('d', tB); R.bThighOl.setAttribute('d', tB);
    R.bShin.setAttribute('d', seg(kb, ab));
    R.bKnee.setAttribute('cx', kb.x.toFixed(2)); R.bKnee.setAttribute('cy', kb.y.toFixed(2));

    // body rocks around the hip (hip stays on the saddle), head bobs, wings sway
    R.torso.setAttribute('transform', 'rotate(' + (0.9 * Math.sin(rad)).toFixed(3) + ' ' + HIP_A.x + ' ' + HIP_A.y + ')');
    R.head.setAttribute('transform', 'translate(0 ' + (1.6 * tw).toFixed(3) + ') rotate(' + (1.2 * Math.sin(2 * rad + 0.8)).toFixed(3) + ' 466 112)');
    R.wingNear.setAttribute('transform', 'rotate(' + (0.7 * tw).toFixed(3) + ' 556 262)');
    R.wingFar.setAttribute('transform', 'rotate(' + (-0.7 * tw).toFixed(3) + ' 538 242)');

    // chain + scrolling ground (all offsets wrap exactly once per cycle)
    R.chain.setAttribute('stroke-dashoffset', (-mod(p * CHAIN_CIRC, CHAIN_TILE)).toFixed(4));
    var road = mod(p * WHEEL_CIRC, ROAD_TILE);
    R.marks.setAttribute('transform', tr(-road, 0));
    R.tufts.setAttribute('transform', tr(-mod(p * WHEEL_CIRC, ROAD_TILE / 2), 0));
    R.trees.setAttribute('transform', tr(-mod(p * TREE_TILE, TREE_TILE), 0));
    R.hillsNear.setAttribute('transform', tr(-mod(p * HILL_NEAR, HILL_NEAR), 0));
    R.hillsFar.setAttribute('transform', tr(-mod(p * HILL_FAR, HILL_FAR), 0));
  }

  function renderControls() {
    var lbl = state.paused ? '继续' : '暂停';
    $('icon-pause').setAttribute('display', state.paused ? 'none' : 'inline');
    $('icon-play').setAttribute('display', state.paused ? 'inline' : 'none');
    $('play-label').textContent = lbl;
    $('play-title').textContent = lbl;
    R.play.setAttribute('aria-label', lbl);
    R.play.setAttribute('aria-pressed', state.paused ? 'true' : 'false');
    $('speed-label').textContent = state.rate + '× 速度';
    $('speed-title').textContent = '切换速度（当前 ' + state.rate + '×）';
    R.speed.setAttribute('aria-label', '速度 ' + state.rate + ' 倍，点击切换到 ' + (state.rate === 1 ? 2 : 1) + ' 倍');
    $('speed-needle').setAttribute('d', state.rate === 1 ? 'M28 28 L22 19' : 'M28 28 L35 19');
  }

  function advance(seconds) {
    if (state.paused) return;
    var s = Number(seconds);
    if (!isFinite(s)) return;
    state.phase = mod(state.phase + s * state.rate / CYCLE, 1);
    if (state.phase >= 1) state.phase = 0;
  }

  function togglePause() { state.paused = !state.paused; lastT = null; renderControls(); render(); }
  function toggleSpeed() { state.rate = state.rate === 1 ? 2 : 1; renderControls(); render(); }

  function bindButton(node, fn) {
    node.addEventListener('click', function (e) { e.preventDefault(); fn(); });
    node.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); fn(); }
    });
  }
  bindButton(R.play, togglePause);
  bindButton(R.speed, toggleSpeed);

  function frame(t) {
    if (lastT === null || manual || state.paused) {
      lastT = t;
    } else {
      var dt = Math.min(0.1, Math.max(0, (t - lastT) / 1000));
      lastT = t;
      advance(dt);
      render();
    }
    requestAnimationFrame(frame);
  }

  window.benchPelican = {
    getState: function () { return { phase: state.phase, paused: state.paused, rate: state.rate }; },
    setManualMode: function (flag) { manual = !!flag; lastT = null; },
    step: function (seconds) { advance(seconds); render(); return this.getState(); },
    reset: function () {
      state.phase = 0; state.rate = 1; state.paused = false; lastT = null;
      renderControls(); render();
      return this.getState();
    },
    togglePlay: togglePause,
    toggleSpeed: toggleSpeed
  };

  renderControls();
  render();
  requestAnimationFrame(frame);
})();
